list_blog_categories.code:
import (
	"fmt"
)

resp, err := client.BlogCategories().ListBlogCategories(ctx, map[string]any{"limit": 20, "offset": 0}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["blog_categories"].([]any) {
	category := row.(map[string]any)
	fmt.Println(category["id"], category["name"], category["url"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

